INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7015192, 1060758, 114225, '<td valign="top">Lovely!</td>', 'Lovely!', '2013-04-07 09:23:49.000000', NULL, 1),
(7015195, 1061382, 114225, '<td valign="top">The reflections in the wood is a great touch.</td>', 'The reflections in the wood is a great touch.', '2013-04-07 09:24:14.000000', NULL, 1),
(7015229, 1061905, 63218, '<td valign="top">The longer I keep this up on my screen, the better it looks!</td>', 'The longer I keep this up on my screen, the better it looks!', '2013-04-07 10:33:16.000000', NULL, 1),
(7015231, 1061922, 63218, '<td valign="top">Priceless!</td>', 'Priceless!', '2013-04-07 10:41:48.000000', NULL, 1),
(7015335, 1061886, 138630, '<td valign="top">This is my top pick in Duotones.  I love everything about it: the full frame composition, the lighting on the petal edges, the palpable textures, the droplets, and the way it positively pops out of the frame.  Add to that the fact that the tones are exquisite and just perfect for the subject (not so easy, I''ve found) and you have a winner in my book.  10  Voted earlier; back to comment.</td>', 'This is my top pick in Duotones.  I love everything about it: the full frame composition, the lighting on the petal edges, the palpable textures, the droplets, and the way it positively pops out of the frame.  Add to that the fact that the tones are exquisite and just perfect for the subject (not so easy, I''ve found) and you have a winner in my book.  10  Voted earlier; back to comment.', '2013-04-07 12:47:35.000000', NULL, 1),
(7015338, 1061305, 138630, '<td valign="top">A lovely pair, beautifully captured - looks as if they are having a very intimate moment or at least a lovely, private conversation.  Nice tones.  Top 10 for me.  Voted earlier; back to comment.</td>', 'A lovely pair, beautifully captured - looks as if they are having a very intimate moment or at least a lovely, private conversation.  Nice tones.  Top 10 for me.  Voted earlier; back to comment.', '2013-04-07 12:49:30.000000', NULL, 1),
(7015342, 1060847, 138630, '<td valign="top">I kept coming back and back.  I love the simplicity of the set-up and the fact that the old fashioned look and feel is maintained throughout the image: bowl, chair, fresh fruit, and tones are all suitably retro.  Top 10.  Voted earlier; back to comment.</td>', 'I kept coming back and back.  I love the simplicity of the set-up and the fact that the old fashioned look and feel is maintained throughout the image: bowl, chair, fresh fruit, and tones are all suitably retro.  Top 10.  Voted earlier; back to comment.', '2013-04-07 12:51:30.000000', NULL, 1),
(7015345, 1061382, 138630, '<td valign="top">Caught my eye from the first time through the entries.  I love the glow on this and the tones are lovely.  Maybe a bit soft for me and I could use a tad more detail in the highlights, but still a top pick.  9  Voted earlier; back to comment.</td>', 'Caught my eye from the first time through the entries.  I love the glow on this and the tones are lovely.  Maybe a bit soft for me and I could use a tad more detail in the highlights, but still a top pick.  9  Voted earlier; back to comment.', '2013-04-07 12:53:11.000000', NULL, 1),
(7015347, 1061485, 138630, '<td valign="top">Quite a lovely scene, beautifully photographed and presented in these grayed blue tones.  Nice.  Top 10.  Voted earlier; back to comment.</td>', 'Quite a lovely scene, beautifully photographed and presented in these grayed blue tones.  Nice.  Top 10.  Voted earlier; back to comment.', '2013-04-07 12:54:09.000000', NULL, 1),
(7015350, 1061731, 138630, '<td valign="top">Delightful scene and the crispness and clarity are extremely pleasing.  I regret the banding in the sky but the tones are excellent and perfect for the scene so this remains a favorite.  Top 10.  Voted earlier; back to comment.</td>', 'Delightful scene and the crispness and clarity are extremely pleasing.  I regret the banding in the sky but the tones are excellent and perfect for the scene so this remains a favorite.  Top 10.  Voted earlier; back to comment.', '2013-04-07 12:55:10.000000', NULL, 1),
(7015353, 1061609, 138630, '<td valign="top">Not sure what I''m looking at here - a model of an Escher work, perhaps?  At any rate, it''s very clever and eye-catching and the crisp lines and nice tones put it right up there with my top picks.  Too bad the fingers are blown out - though maybe that helps set them off from the busyness elsewhere.  9  Voted earlier; back to comment.</td>', 'Not sure what I''m looking at here - a model of an Escher work, perhaps?  At any rate, it''s very clever and eye-catching and the crisp lines and nice tones put it right up there with my top picks.  Too bad the fingers are blown out - though maybe that helps set them off from the busyness elsewhere.  9  Voted earlier; back to comment.', '2013-04-07 12:57:48.000000', NULL, 1),
(7015354, 1061466, 138630, '<td valign="top">Fine scene, beautiful back-lighting, excellent action capture, wonderful warm tones.  Very pleasing.  Top 10 for me.  Voted earlier; back to comment.</td>', 'Fine scene, beautiful back-lighting, excellent action capture, wonderful warm tones.  Very pleasing.  Top 10 for me.  Voted earlier; back to comment.', '2013-04-07 12:58:37.000000', NULL, 1),
