(7016645, 1061795, 126939, '<td valign="top">Thank You for the great comments. I shot this on the west side of Vermillion Lakes outside of Banff Alberta. A dozen camera hunters were out shooting a Mount Rundle Sunrise. I was chasing the moon. The light on the mountain peak is fron the sunrise as the moon came clear. the crop factor was 50%.</td>', 'Thank You for the great comments. I shot this on the west side of Vermillion Lakes outside of Banff Alberta. A dozen camera hunters were out shooting a Mount Rundle Sunrise. I was chasing the moon. The light on the mountain peak is fron the sunrise as the moon came clear. the crop factor was 50%.', '2013-04-08 20:16:11.000000', NULL, 0),
(7016663, 1061795, 29490, '<td valign="top">Beautiful photo - congratulations on the blue!</td>', 'Beautiful photo - congratulations on the blue!', '2013-04-08 21:29:08.000000', NULL, 0),
(7016664, 1061466, 29490, '<td valign="top">Nice - congrats on your ribbon :)</td>', 'Nice - congrats on your ribbon :)', '2013-04-08 21:29:59.000000', NULL, 0),
(7016665, 1061147, 29490, '<td valign="top">Congrats on your ribbon, Paul :)<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by LydiaToo:</b></div><hr/><i>This almost never happens on our kitchen table.</i></td></tr></table> <br/>Almost?!?<br/></td>', 'Congrats on your ribbon, Paul :) Originally posted by LydiaToo:This almost never happens on our kitchen table. Almost?!?', '2013-04-08 21:32:02.000000', NULL, 0),
(7016666, 1060455, 29490, '<td valign="top">Nicely seen scene, and beautifully photographed too :)</td>', 'Nicely seen scene, and beautifully photographed too :)', '2013-04-08 21:34:56.000000', NULL, 0),
(7016667, 1061371, 10785, '<td valign="top">You definitely caught the mood in your processing. I like the line of the trail leading into the woods. It''s a great scene and I think it could only be made better with a person fearfully walking into the woods.</td>', 'You definitely caught the mood in your processing. I like the line of the trail leading into the woods. It''s a great scene and I think it could only be made better with a person fearfully walking into the woods.', '2013-04-08 21:39:41.000000', NULL, 0),
(7016704, 1061704, 136989, '<td valign="top">I actually like the blue as compared to you b/w outake.  However both are terrific. I love the reflection in the ripples.</td>', 'I actually like the blue as compared to you b/w outake.  However both are terrific. I love the reflection in the ripples.', '2013-04-08 23:18:21.000000', NULL, 0),
(7016750, 1061147, 67697, '<td valign="top">This is beautiful Paul.  Congrats on the yellow!</td>', 'This is beautiful Paul.  Congrats on the yellow!', '2013-04-09 00:59:48.000000', NULL, 0),
(7016789, 1061923, 113591, '<td valign="top">Good colour tones, and perfect timing! Both in the comp and shutterspeed. Brilliant.<br/> <br/></td>', 'Good colour tones, and perfect timing! Both in the comp and shutterspeed. Brilliant. ', '2013-04-09 02:29:45.000000', NULL, 0),
(7016800, 1061777, 113591, '<td valign="top">I would have had such a sense of achievement to get the image like this without duotoning.</td>', 'I would have had such a sense of achievement to get the image like this without duotoning.', '2013-04-09 03:14:11.000000', NULL, 0),
(7016810, 1061795, 97225, '<td valign="top">Congratulations on the blue (that''s colour coordination!). Beautiful shot.</td>', 'Congratulations on the blue (that''s colour coordination!). Beautiful shot.', '2013-04-09 03:39:36.000000', NULL, 0),
(7016811, 1061466, 97225, '<td valign="top">Congratulations Pam. Great shot - lovely light and dust.</td>', 'Congratulations Pam. Great shot - lovely light and dust.', '2013-04-09 03:41:10.000000', NULL, 0),
(7016812, 1061147, 97225, '<td valign="top">Congratulations Paul. Beautiful work.</td>', 'Congratulations Paul. Beautiful work.', '2013-04-09 03:43:19.000000', NULL, 0),
(7016813, 1061485, 97225, '<td valign="top">Congratulations on the HM. Lovely photo.</td>', 'Congratulations on the HM. Lovely photo.', '2013-04-09 03:44:34.000000', NULL, 0),
(7016814, 1060455, 97225, '<td valign="top">Congratulations on 5th. Beautiful, evocative scene.</td>', 'Congratulations on 5th. Beautiful, evocative scene.', '2013-04-09 03:46:12.000000', NULL, 0),
(7016818, 1060390, 49109, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Ann:</b></div><hr/><i> ... then toning it with just the right amount of brown.  </i></td></tr></table> <br/>Actually it is toned with purple (shadows) and yellow (lights)</td>', 'Originally posted by Ann: ... then toning it with just the right amount of brown.   Actually it is toned with purple (shadows) and yellow (lights)', '2013-04-09 05:22:17.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7016874, 1061466, 82707, '<td valign="top">Congrats on Red!  Beautiful image!  Wish I was there... :)</td>', 'Congrats on Red!  Beautiful image!  Wish I was there... :)', '2013-04-09 09:38:08.000000', NULL, 0),
(7016894, 1061795, 61961, '<td valign="top">Gorgeous, contrats on the well-deserved ribbon.</td>', 'Gorgeous, contrats on the well-deserved ribbon.', '2013-04-09 10:22:41.000000', NULL, 0),
(7016895, 1061466, 61961, '<td valign="top">Lovely light, congrats on the ribbon.</td>', 'Lovely light, congrats on the ribbon.', '2013-04-09 10:23:06.000000', NULL, 0),
(7016898, 1061147, 61961, '<td valign="top">Intriguing image, congrats on the ribbon.  It''s disconcerting to try to focus on her face.  Is she wearing a mask, or am I seeing things?</td>', 'Intriguing image, congrats on the ribbon.  It''s disconcerting to try to focus on her face.  Is she wearing a mask, or am I seeing things?', '2013-04-09 10:25:27.000000', NULL, 0),
(7016900, 1061231, 61961, '<td valign="top">Striking photo!  Really jumps out of the crowd.</td>', 'Striking photo!  Really jumps out of the crowd.', '2013-04-09 10:28:32.000000', NULL, 0),
(7016908, 1061147, 100393, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by citymars:</b></div><hr/><i> Intriguing image, congrats on the ribbon.  It''s disconcerting to try to focus on her face.  Is she wearing a mask, or am I seeing things? </i></td></tr></table> <br/> <br/>Her whole head is behind the net curtain so it''s partially opaque.</td>', 'Originally posted by citymars: Intriguing image, congrats on the ribbon.  It''s disconcerting to try to focus on her face.  Is she wearing a mask, or am I seeing things?   Her whole head is behind the net curtain so it''s partially opaque.', '2013-04-09 10:34:15.000000', NULL, 0),
(7016942, 1061890, 118154, '<td valign="top">This is a very nice image of this type,Congrats.</td>', 'This is a very nice image of this type,Congrats.', '2013-04-09 11:14:05.000000', NULL, 0),
(7016954, 1061147, 68956, '<td valign="top">I can see one and a half eyes, two mouths and a bulging skull. It looks very strange? Especially the two mouths, they are very clear.</td>', 'I can see one and a half eyes, two mouths and a bulging skull. It looks very strange? Especially the two mouths, they are very clear.', '2013-04-09 11:23:21.000000', NULL, 0),
(7016961, 1061147, 100393, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Chinarosepetal:</b></div><hr/><i> I can see one and a half eyes, two mouths and a bulging skull. It looks very strange? Especially the two mouths, they are very clear. </i></td></tr></table> <br/> <br/>Have a look at it <a href="//1x.com/photo/97336/" rel="nofollow" target="_blank">here</a>. It''s a larger version and may be clearer.</td>', 'Originally posted by Chinarosepetal: I can see one and a half eyes, two mouths and a bulging skull. It looks very strange? Especially the two mouths, they are very clear.   Have a look at it here. It''s a larger version and may be clearer.', '2013-04-09 11:31:07.000000', NULL, 0),
(7016972, 1061147, 68956, '<td valign="top">Thanks Paul. Even in the larger version I''m still seeing the 1.5 eyes and 2 mouths - what are those two dark lines (above her R hand?)</td>', 'Thanks Paul. Even in the larger version I''m still seeing the 1.5 eyes and 2 mouths - what are those two dark lines (above her R hand?)', '2013-04-09 12:15:15.000000', NULL, 0),
(7016993, 1061147, 100393, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Chinarosepetal:</b></div><hr/><i> Thanks Paul. Even in the larger version I''m still seeing the 1.5 eyes and 2 mouths - what are those two dark lines (above her R hand?) </i></td></tr></table> <br/> <br/>We are seeing her left eye (on the right for the viewer), that upper quadrant of her face and the rest is covered by a sweep of her hair. Does that help? :-)</td>', 'Originally posted by Chinarosepetal: Thanks Paul. Even in the larger version I''m still seeing the 1.5 eyes and 2 mouths - what are those two dark lines (above her R hand?)   We are seeing her left eye (on the right for the viewer), that upper quadrant of her face and the rest is covered by a sweep of her hair. Does that help? :-)', '2013-04-09 12:39:44.000000', NULL, 0),
(7017016, 1061147, 68956, '<td valign="top">This is what I''m seeing - a sort of melted, half obscured face.<br/><img alt="'' . substr(''//i47.tinypic.com/2vma351.jpg'', strrpos(''//i47.tinypic.com/2vma351.jpg'', ''/'') + 1) . ''" border="0" src="//i47.tinypic.com/2vma351.jpg"/></td>', 'This is what I''m seeing - a sort of melted, half obscured face.', '2013-04-09 13:42:01.000000', NULL, 0),
(7017019, 1061147, 68956, '<td valign="top">I think I''m getting it now, maybe it''s just the material distorting things slightly, then me interpreting the hair as a mouth. Trouble is once you''ve seen something one way it''s difficult to lose it from your mind!</td>', 'I think I''m getting it now, maybe it''s just the material distorting things slightly, then me interpreting the hair as a mouth. Trouble is once you''ve seen something one way it''s difficult to lose it from your mind!', '2013-04-09 13:48:22.000000', NULL, 0),
(7017022, 1061147, 100393, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Chinarosepetal:</b></div><hr/><i> I think I''m getting it now, maybe it''s just the material distorting things slightly, then me interpreting the hair as a mouth. Trouble is once you''ve seen something one way it''s difficult to lose it from your mind! </i></td></tr></table> <br/> <br/>I know what you mean. Here it is with just a bit of added definition, no other edit at 100% from the RAW file:<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1063419" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_1063419.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_1063419.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_1063419.jpg"/></a> <br/> <br/>Her whole head is behind the curtain, her hair covers most of her right side of her face. We just see her mouth above the locks of hair that cover the chin. Her nose looks odd because it in contact with the fabric and causing a shadow on the fabric.<br/> <br/>I''m sure that clears it up.<br/> <br/>:-)</td>', 'Originally posted by Chinarosepetal: I think I''m getting it now, maybe it''s just the material distorting things slightly, then me interpreting the hair as a mouth. Trouble is once you''ve seen something one way it''s difficult to lose it from your mind!   I know what you mean. Here it is with just a bit of added definition, no other edit at 100% from the RAW file:   Her whole head is behind the curtain, her hair covers most of her right side of her face. We just see her mouth above the locks of hair that cover the chin. Her nose looks odd because it in contact with the fabric and causing a shadow on the fabric. I''m sure that clears it up. :-)', '2013-04-09 14:01:26.000000', NULL, 0),
